<div class="card border-0 shadow-sm mb-4"><div class="card-body"><h3 class="h6 mb-3">Add Daily Work</h3><form method="post" enctype="multipart/form-data" action="<?= e(app_url('/labour/work')) ?>"><input type="hidden" name="<?= e((string)env('CSRF_TOKEN_NAME', 'csrf_token')) ?>" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-2"><label class="form-label">Date</label><input type="date" name="date" value="<?= e(date('Y-m-d')) ?>" class="form-control" required></div><div class="col-md-3"><label class="form-label">Project</label><select name="project_id" class="form-select"><option value="">Select project</option><?php foreach ($projects as $project): ?><option value="<?= e($project['id']) ?>"><?= e($project['id'] . ' - ' . $project['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Block</label><input name="block" class="form-control"></div><div class="col-md-2"><label class="form-label">Floor</label><input name="floor" class="form-control"></div><div class="col-md-3"><label class="form-label">Activity</label><input name="activity" class="form-control" required></div><div class="col-md-4"><label class="form-label">Description</label><textarea name="description" rows="2" class="form-control"></textarea></div><div class="col-md-2"><label class="form-label">Labour Count</label><input type="number" min="0" name="labour_count" class="form-control"></div><div class="col-md-3"><label class="form-label">Contractor</label><select name="contractor_id" class="form-select"><option value="">Select contractor</option><?php foreach ($contractors as $contractor): ?><option value="<?= e($contractor['id']) ?>"><?= e($contractor['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Supervisor</label><input name="supervisor" class="form-control"></div><div class="col-md-2"><label class="form-label">Planned Qty</label><input type="number" step="0.01" min="0" name="planned_quantity" class="form-control"></div><div class="col-md-2"><label class="form-label">Completed Qty</label><input type="number" step="0.01" min="0" name="completed_quantity" class="form-control"></div><div class="col-md-2"><label class="form-label">Unit</label><input name="unit" class="form-control" placeholder="sqft, m3"></div><div class="col-md-2"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach (['Pending','In Progress','Completed','Delayed'] as $status): ?><option><?= e($status) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Before Image</label><input type="file" name="before_image" accept="image/*" class="form-control"></div><div class="col-md-3"><label class="form-label">After Image</label><input type="file" name="after_image" accept="image/*" class="form-control"></div><div class="col-md-3"><label class="form-label">Materials Used</label><input name="materials_used" class="form-control"></div><div class="col-md-3"><label class="form-label">Issues</label><input name="issues" class="form-control"></div><div class="col-md-6"><label class="form-label">Next Day Plan</label><textarea name="next_day_plan" rows="2" class="form-control"></textarea></div><div class="col-md-6"><label class="form-label">Remarks</label><textarea name="remarks" rows="2" class="form-control"></textarea></div></div><button class="btn btn-accent mt-3">Save Daily Work</button></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Date</th><th>Project / Activity</th><th>Contractor</th><th>Labour</th><th>Quantity</th><th>Progress</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= e(format_date($record['date'])) ?></td><td><strong><?= e($record['activity']) ?></strong><div class="small text-muted"><?= e(($record['project_name'] ?? '-') . ' / Block ' . ($record['block'] ?? '-') . ' / Floor ' . ($record['floor'] ?? '-')) ?></div></td><td><?= e($record['contractor_name'] ?? '-') ?></td><td><?= e($record['labour_count']) ?></td><td><?= e($record['completed_quantity'] . ' / ' . $record['planned_quantity'] . ' ' . ($record['unit'] ?? '')) ?></td><td><?= e(number_format((float)$record['completion_percentage'], 1)) ?>%</td><td><span class="badge text-bg-<?= $record['status'] === 'Delayed' ? 'danger' : ($record['status'] === 'Completed' ? 'success' : 'warning') ?>"><?= e($record['status']) ?></span></td><td><form method="post" action="<?= e(app_url('/labour/work/' . $record['id'] . '/delete')) ?>" onsubmit="return confirm('Delete this work record?')"><input type="hidden" name="<?= e((string)env('CSRF_TOKEN_NAME', 'csrf_token')) ?>" value="<?= e(csrf_token()) ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>
